// Get the current company from Apify scrape result
const currentItem = $input.item.json;
const currentCompanyName = currentItem.companyName;

// Get the master list from the first node (stored in workflow static data or passed through)
// We need to access the master list that was read at the beginning
// In n8n, we can use $node to access data from other nodes

const masterListData = $('Google Sheets - Read Master List ONCE').all();

// Check if this company already exists in the master list
let companyExists = false;

if (currentCompanyName) {
  companyExists = masterListData.some(item => {
    const masterCompanyName = item.json.companyName;
    if (masterCompanyName && currentCompanyName) {
      return masterCompanyName.toLowerCase().trim() === currentCompanyName.toLowerCase().trim();
    }
    return false;
  });
}

// If company does NOT exist, pass it through for processing
// If company DOES exist, return empty array to skip it
if (!companyExists) {
  return { 
    json: {
      ...currentItem,
      _companyIsNew: true,
      _companyChecked: true
    }
  };
} else {
  // Company exists, skip it
  return [];
}
